<?php
require_once __DIR__.'/lesson_book_excel.php';
function th_personal_ranges(array $actual,string $personKey):array{
 $selected=array_values(array_filter($actual,fn($r)=>$r['person']['key']===$personKey));usort($selected,fn($a,$b)=>[$a['subject']??'',$a['class']??'',$a['category'],(int)($a['ppct_period']??0),$a['date']]<=>[$b['subject']??'',$b['class']??'',$b['category'],(int)($b['ppct_period']??0),$b['date']]);$out=[];
 foreach($selected as$r){$period=(int)($r['ppct_period']??0);$key=implode('|',[$r['subject']??'',$r['class']??'',$r['category']]);$last=count($out)-1;
 if($last>=0&&$period>0&&$r['quantity']===1.0&&$out[$last]['simple']&&$out[$last]['key']===$key&&$out[$last]['to']+1===$period){$out[$last]['to']=$period;$out[$last]['quantity']+=1;$out[$last]['date_from']=min($out[$last]['date_from'],$r['date']);$out[$last]['date_to']=max($out[$last]['date_to'],$r['date']);}
 else $out[]=['key'=>$key,'subject'=>$r['subject']??'','class'=>$r['class']??'','category'=>$r['category'],'from'=>$period>0?$period:'','to'=>$period>0?$period:'','quantity'=>$r['quantity'],'simple'=>$period>0&&$r['quantity']===1.0,'date_from'=>$r['date'],'date_to'=>$r['date']];
 }return $out;
}
function th_export_sheets(array $actual,array $roles,array $totals,string $format):array{
 $groups=[];$teacher=[];$i=0;
 foreach($totals as$t){$p=$t['person'];$extra=$t['tn']+$t['vao10']+$t['hsg'];$teacher[]=[++$i,$p['code'],$p['name'],$p['group'],$t['main'],$t['roles'],$extra,$t['other'],$t['total'],'','','',''];$g=$p['group']?:'Chưa xác định tổ';if(!isset($groups[$g]))$groups[$g]=array_fill(0,6,0);foreach([$t['main'],$t['roles'],$extra,$t['other'],$t['total'],$t['actual']]as$k=>$v)$groups[$g][$k]+=$v;}
 $groupRows=[];$i=0;foreach($groups as$name=>$v)$groupRows[]=[++$i,$name,$v[0],$v[1],$v[2],$v[3],$v[4],'','',''];
 $roleRows=[];$i=0;foreach($roles as$r)$roleRows[]=[++$i,$r['code'],$r['teacher'],$r['role'],$r['scope'],$r['rate'],$r['weeks'],$r['quantity'],$r['from'],$r['to'],$r['note']];
 $training=[];$i=0;foreach($totals as$t)$training[]=[++$i,$t['person']['code'],$t['person']['name'],$t['tn'],$t['vao10'],$t['hsg'],$t['other'],$t['tn']+$t['vao10']+$t['hsg']];
 $details=[];foreach($actual as$r)$details[]=[$r['date'],$r['person']['code'],$r['teacher'],$r['actual_teacher']??'',$r['subject']??'',$r['class']??'',$r['session']??'',$r['period']??'',$r['ppct_period']??'',$r['lesson_title']??'',th_categories()[$r['category']],$r['quantity'],$r['signed_at'],$r['report_id']];
 $sum=fn($key)=>array_sum(array_column($totals,$key));
 if($totals){$groupRows[]=['','Tổng cộng',$sum('main'),$sum('roles'),$sum('tn')+$sum('vao10')+$sum('hsg'),$sum('other'),$sum('total'),'','',''];$teacher[]=['','','Tổng cộng','',$sum('main'),$sum('roles'),$sum('tn')+$sum('vao10')+$sum('hsg'),$sum('other'),$sum('total'),'','','',''];$training[]=['','','Tổng cộng',$sum('tn'),$sum('vao10'),$sum('hsg'),$sum('other'),$sum('tn')+$sum('vao10')+$sum('hsg')];}
 if($roles)$roleRows[]=['','','Tổng cộng','','','','',array_sum(array_column($roles,'quantity')),'','',''];
 $sheets=[
 ['name'=>'Phụ lục 1','title'=>'BIỂU TỔNG HỢP KÊ KHAI KHỐI LƯỢNG GIẢNG DẠY','heads'=>['TT','Tổ/nhóm chuyên môn','Tiết thực dạy chính khóa','Tiết kiêm nhiệm','Ôn TN, vào 10, HSG','Chưa phân loại / khác','Tổng tiết thực hiện','Định mức/năm','Vượt định mức','Ghi chú'],'widths'=>[7,28,17,15,20,20,18,16,16,30],'rows'=>$groupRows],
 ['name'=>'Phụ lục 2','title'=>'BIỂU KÊ KHAI CHI TIẾT THEO GIÁO VIÊN','heads'=>['TT','Mã GV','Họ và tên GV','Tổ/nhóm','Tiết thực dạy chính khóa','Tiết kiêm nhiệm','Ôn TN, vào 10, HSG','Chưa phân loại / khác','Tổng tiết thực hiện','Định mức/năm','Vượt định mức','Bù trừ','Được thanh toán'],'widths'=>[7,18,30,22,17,15,20,20,18,16,16,14,18],'rows'=>$teacher],
 ['name'=>'Phụ lục 3','title'=>'TỔNG SỐ TIẾT KIÊM NHIỆM','heads'=>['TT','Mã GV','Giáo viên','Công tác kiêm nhiệm','Lớp/phạm vi','Tiết/tuần','Số tuần tính','Tổng tiết kiêm nhiệm','Từ ngày','Đến ngày','Ghi chú/căn cứ'],'widths'=>[7,18,30,35,18,13,14,19,14,14,40],'rows'=>$roleRows],
 ['name'=>'Ôn thi riêng','title'=>'TỔNG HỢP RIÊNG ÔN THI TỐT NGHIỆP, VÀO 10, HỌC SINH GIỎI','heads'=>['TT','Mã GV','Giáo viên','Ôn thi TN','Ôn thi vào 10','Ôn HSG','Chưa phân loại / khác','Tổng ôn thi'],'widths'=>[7,18,30,16,18,16,23,18],'rows'=>$training],
 ['name'=>'Đối chiếu sổ ký','title'=>'CHI TIẾT TIẾT THỰC DẠY ĐÃ KÝ SỔ','heads'=>['Ngày dạy','Mã GV','Người ký','GV thực tế','Môn','Lớp','Buổi','Tiết TKB','Tiết PPCT','Nội dung','Nhóm','Số tiết thực tế','Thời gian ký','Mã tiết'],'widths'=>[14,18,30,30,24,12,12,12,12,55,22,15,28,40],'rows'=>$details],
 ];
 if($format==='personal'||$format==='all')foreach($totals as$t){$p=$t['person'];$rows=[];$i=0;foreach(th_personal_ranges($actual,$p['key'])as$r)$rows[]=[++$i,$r['subject'],$r['class'],$r['from'],$r['to'],$r['quantity'],'','','',th_categories()[$r['category']].' · '.$r['date_from'].($r['date_to']!==$r['date_from']?' – '.$r['date_to']:'')];
 foreach($roles as$r)if($r['person_key']===$p['key'])$rows[]=['','','','','','',$r['role'].($r['scope']?' · '.$r['scope']:''),$r['weeks'],$r['quantity'],$r['from'].' – '.$r['to'].' · '.$r['rate'].' tiết/tuần'];
 $rows[]=['Tổng','','','','',$t['actual'],'','',$t['roles'],'Tổng thực hiện: '.$t['total']];
 $sheets[]=['name'=>$p['name'],'title'=>'BẢNG KÊ CÁ NHÂN – '.$p['name'].' – '.$p['code'],'heads'=>['STT','Môn','Lớp dạy','Từ tiết PPCT','Đến tiết PPCT','Tổng tiết thực dạy','Công việc kiêm nhiệm','Số tuần','Tổng tiết kiêm nhiệm','Ghi chú'],'widths'=>[7,26,12,16,16,19,35,13,21,50],'rows'=>$rows];}
 if($format==='personal')$sheets=array_slice($sheets,5);return $sheets;
}
function th_export_sheet(array $sheet,string $school,string $period,string $note):string{
 $lastCol=lb_xlsx_col(count($sheet['heads']));$last=max(6,count($sheet['rows'])+6);$cols='';foreach($sheet['widths']as$i=>$w)$cols.='<col min="'.($i+1).'" max="'.($i+1).'" width="'.$w.'" customWidth="1"/>';
 $xml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><sheetViews><sheetView workbookViewId="0" showGridLines="0"><pane ySplit="6" topLeftCell="A7" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="25"/><cols>'.$cols.'</cols><sheetData>';
 foreach([1=>$school,2=>$sheet['title'],3=>'Khoảng ngày dạy: '.$period,4=>$note]as$r=>$value)$xml.='<row r="'.$r.'" ht="'.($r===4?42:30).'" customHeight="1">'.lb_xlsx_text('A'.$r,$value,$r===2?1:0).'</row>';
 $xml.='<row r="6" ht="42" customHeight="1">';foreach($sheet['heads']as$i=>$h)$xml.=lb_xlsx_text(lb_xlsx_col($i+1).'6',$h,2);$xml.='</row>';
 foreach($sheet['rows']as$i=>$row){$n=$i+7;$height=28;foreach($row as$j=>$v)if(is_string($v))$height=max($height,min(200,16*ceil(mb_strlen($v)/max(5,$sheet['widths'][$j]-3))+8));$xml.='<row r="'.$n.'" ht="'.$height.'" customHeight="1">';foreach($row as$j=>$v)$xml.=is_int($v)||is_float($v)?lb_xlsx_number(lb_xlsx_col($j+1).$n,$v,4):lb_xlsx_text(lb_xlsx_col($j+1).$n,$v,3);$xml.='</row>';}
 $n=$last+3;$xml.='<row r="'.$n.'" ht="30">'.lb_xlsx_text('A'.$n,'NGƯỜI LẬP BIỂU',0).lb_xlsx_text(lb_xlsx_col(max(2,(int)ceil(count($sheet['heads'])/2))).$n,'NGƯỜI KIỂM TRA / XÁC NHẬN',0).'</row></sheetData><autoFilter ref="A6:'.$lastCol.$last.'"/><mergeCells count="4">';foreach([1,2,3,4]as$n)$xml.='<mergeCell ref="A'.$n.':'.$lastCol.$n.'"/>';
 return $xml.'</mergeCells><printOptions horizontalCentered="1"/><pageMargins left="0.25" right="0.25" top="0.4" bottom="0.4" header="0.2" footer="0.2"/><pageSetup orientation="landscape" paperSize="9" fitToWidth="1" fitToHeight="0"/><headerFooter><oddFooter>&amp;CTrang &amp;P / &amp;N</oddFooter></headerFooter></worksheet>';
}
function th_export_xlsx(array $actual,array $roles,array $totals,string $from,string $to,string $school,string $format,string $target,array $warnings=[]):bool{
 $sheets=th_export_sheets($actual,$roles,$totals,$format);if($warnings)$sheets[]=['name'=>'Cần đối chiếu','title'=>'CÁC NỘI DUNG CẦN ĐỐI CHIẾU TRƯỚC KHI CHỐT','heads'=>['STT','Nội dung'],'widths'=>[8,130],'rows'=>array_map(fn($i,$w)=>[$i+1,$w],array_keys($warnings),$warnings)];if(!$sheets)throw new RuntimeException('Không có dữ liệu trong phạm vi đã chọn.');
 $files=lb_xlsx_base_files('Tổng hợp giờ dạy','Tổng hợp','',lb_xlsx_styles());$ws='';$rels='';$types='';$names=[];$defined='';
 foreach($sheets as$i=>$sheet){$id=$i+1;$name=mb_substr(preg_replace('~[\\\\/?*\[\]:]~u',' ',$sheet['name']),0,31);$base=$name;$suffix=1;while(isset($names[mb_strtolower($name)])){$tail=' '.++$suffix;$name=mb_substr($base,0,31-mb_strlen($tail)).$tail;}$names[mb_strtolower($name)]=true;
 $ws.='<sheet name="'.lb_xlsx_xml($name).'" sheetId="'.$id.'" r:id="rId'.$id.'"/>';$rels.='<Relationship Id="rId'.$id.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'.$id.'.xml"/>';$types.='<Override PartName="/xl/worksheets/sheet'.$id.'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>';
 $note='Số liệu khối lượng; chưa xác định định mức, bù trừ, số tiết và tiền được thanh toán. Kiêm nhiệm = tiết/tuần × số tuần đã khai.';
 $files['xl/worksheets/sheet'.$id.'.xml']=th_export_sheet($sheet,$school,$from.' – '.$to,$note);$defined.='<definedName name="_xlnm.Print_Titles" localSheetId="'.$i.'">'.lb_xlsx_xml("'".str_replace("'","''",$name)."'!$1:$6").'</definedName>';}
 $files['xl/workbook.xml']='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><bookViews><workbookView/></bookViews><sheets>'.$ws.'</sheets><definedNames>'.$defined.'</definedNames></workbook>';
 $files['xl/_rels/workbook.xml.rels']='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'.$rels.'<Relationship Id="rId'.(count($sheets)+1).'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>';
 $files['[Content_Types].xml']=preg_replace('~<Override PartName="/xl/worksheets/sheet1.xml"[^>]*/>~',$types,$files['[Content_Types].xml']);$files['docProps/app.xml']='<?xml version="1.0" encoding="UTF-8"?><Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties"><Application>CDS</Application></Properties>';return lb_xlsx_zip($files,$target);
}
